  ("KsOrganisationalObservation", "organisational observation", "observation organisationnelle", "A fact recorded about a given organisation, such as a configuration or a test result.", "Fait consigné au sujet d'une organisation donnée, comme une configuration ou un résultat d'essai."),
  ("KsAnalyticalHypothesis", "analytical hypothesis (knowledge status)", "hypothèse explicative (statut épistémique)", "A proposed explanation not yet tested against evidence.", "Explication proposée qui n'a pas encore été vérifiée au regard des preuves."),
  ("KsRiskEstimate", "risk estimate", "estimation de risque", "A model or expert estimate of likelihood, impact or risk.", "Estimation, par un modèle ou un expert, d'une vraisemblance, d'un impact ou d'un risque."),
  ("KsAuditConclusion", "audit conclusion (knowledge status)", "conclusion d'audit (statut épistémique)", "A conclusion reached by an assessor against criteria on the basis of evidence.", "Conclusion à laquelle arrive un évaluateur au regard de critères sur la base de preuves."),
