  ("DistUniform", "uniform", "uniforme", "Every value between a minimum and a maximum is equally likely.", "Toutes les valeurs entre un minimum et un maximum sont également probables."),
  ("DistTriangular", "triangular", "triangulaire", "Defined by a minimum, a most likely value and a maximum.", "Définie par un minimum, une valeur la plus probable et un maximum."),
